def pre(digits):
    return True

def post(digits, result):
    total = 0
    n = len(digits)
    for i in range(n):
        d = digits[n - 1 - i]
        if i % 2 == 1:
            d = d * 2
            if d > 9:
                d = d - 9
        total += d
    expected = (total % 10 == 0)
    return result == expected
